Fix the CRC calculation that is used to check for changes in profile updates, and verify the binary integrity before applying Bootloader updates. The original implementation failed to pick up changes beyond the first 25% of the input buffer, leading to potential undetected modifications, and invalid bootloader code being flashed.

Example to test the behaviour before / after:

```
#include <cstdint>
#include <cstdio>

static uint32_t CalcFletcher32(uint32_t *startAddr, uint32_t *endAddr)
{
        uint32_t fletcher = 0;
        uint16_t* pData = (uint16_t *)startAddr;
        uint32_t *index = 0;

        uint16_t sum1 = 0;
        uint16_t sum2 = 0;
        for(index = startAddr; index <= endAddr; index +=2)
        {
            sum1 = sum1 + *pData++;
            sum2 = (sum2 + sum1);
        }
        fletcher = (sum2 << 16) | sum1;

        return fletcher;
}

static uint32_t CalcFletcher32_new(uint32_t *startAddr, uint32_t *endAddr)
{
        uint32_t fletcher = 0;

        uint16_t sum1 = 0;
        uint16_t sum2 = 0;
        for(uint16_t *index = (uint16_t *)startAddr; index <= (uint16_t *)endAddr; index++)
        {
            sum1 = sum1 + *index;
            sum2 = (sum2 + sum1);
        }
        fletcher = (sum2 << 16) | sum1;

        return fletcher;
}

static void testCrcCalculation(uint32_t (calculateCrcFunc)(uint32_t *startAddr, uint32_t *endAddr))
{
    char testBuf[] = {
            0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
            0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F,
    };

    uint32_t lastChecksum;
    for (unsigned i = 0; i < sizeof(testBuf); i++) {
            printf("Testing buffer = ");
            for (unsigned j = 0; j < sizeof(testBuf); j++) {
                    printf("0x%02X ", testBuf[j]);
            }

            uint32_t checksum = calculateCrcFunc((uint32_t *)&testBuf[0], (uint32_t *)&testBuf[sizeof(testBuf) - 1]);
            if (i == 0 || checksum != lastChecksum) {
                    printf(", checksum = 0x%08X\n", checksum);
            } else {
                    printf(", checksum = 0x%08X, PROBLEM\n", checksum);
            }

            testBuf[sizeof(testBuf) - 1 - i] = 0x00;

            lastChecksum = checksum;
    }
}

int main()
{
    printf("Testing CalcFletcher32:\n");
    testCrcCalculation(CalcFletcher32);

    printf("Testing CalcFletcher32_new:\n");
    testCrcCalculation(CalcFletcher32_new);
}
```



